        let samples = [0.5f32, -0.5, 0.25, -0.25];
        let out = audio_convert_to_target(&samples, 2, 48_000, 2, 48_000);
        assert_eq!(out.len(), samples.len());
        assert_eq!(out[0], audio_f32_to_i16(0.5));
